// Buttony NocoDB CE wysylaja caly biezacy wiersz w body.data.rows[0] - ten sam
// ksztalt co webhook tabeli (patrz W9 "Button: Generate offer"), tylko bez
// previous_rows (to nie jest zdarzenie zmiany pola, tylko klikniecie).
const row = ($input.first().json.body && $input.first().json.body.data
  && $input.first().json.body.data.rows && $input.first().json.body.data.rows[0])
  || $input.first().json;
const has_cefr = !!(row.cefr_overall && String(row.cefr_overall).trim());
return [{ json: {
  assessment_id: row.Id,
  participant_id: (row.participants && row.participants.Id) || null,
  cefr_overall: row.cefr_overall || '',
  cefr_range: row.cefr_range || '',
  cefr_accuracy: row.cefr_accuracy || '',
  cefr_fluency: row.cefr_fluency || '',
  cefr_communication: row.cefr_communication || '',
  strengths: row.strengths || '',
  gaps: row.gaps || '',
  auditor_notes: row.auditor_notes || '',
  has_cefr,
} }];

// Sklada dane z CRM w jeden tekst kontekstowy dla AI Agenta (system prompt
// z metodyka CoAction siedzi w node "AI Agent" -> System Message, nie tutaj -
// to jedyne miejsce z tresciu do edycji przez osobe nietechniczna).
// "Notatki Przemka" to meetings.notes najnowszego spotkania typu discovery
// dla tego leada (NIE transcript - klient wprost mowi "notatki, bez
// transkrypcji"); "notatki metodyka po demo" to assessments.auditor_notes
// tego wiersza.
const guard = $('Guard').item.json;
const participant = $('Get participant').item.json || {};
const lead = $('Get lead').item.json || {};
const company = $('Get company').item.json || {};
const leadId = lead.Id ?? null;

const allMeetings = $('Fetch meetings').all().map(i => i.json);
const discoveryMeetings = allMeetings.filter(m =>
  m.leads && m.leads.Id === leadId && m.meeting_type === 'discovery');
const latestDiscovery = discoveryMeetings.slice().sort((a, b) =>
  String(b.starts_at || b.UpdatedAt || '').localeCompare(String(a.starts_at || a.UpdatedAt || ''))
)[0] || {};

const methodologist = lead.lead_type === 'B2B' ? 'dorota@coaction.pl' : 'aleksandra@coaction.pl';

const lines = [
  '## Wyniki audytu (ocena CEFR)',
  `Ogolny: ${guard.cefr_overall || 'brak'}`,
  `Zakres jezyka: ${guard.cefr_range || 'brak'}`,
  `Poprawnosc: ${guard.cefr_accuracy || 'brak'}`,
  `Plynnosc: ${guard.cefr_fluency || 'brak'}`,
  `Komunikatywnosc: ${guard.cefr_communication || 'brak'}`,
  `Mocne strony: ${guard.strengths || 'brak danych'}`,
  `Luki: ${guard.gaps || 'brak danych'}`,
  '',
  '## Notatki metodyka po demo/audycie',
  guard.auditor_notes || 'brak notatek',
  '',
  '## Kontekst uczestnika',
  `Imie i nazwisko: ${participant.full_name || 'brak'}`,
  `Stanowisko: ${participant.position || 'brak'}`,
  `Kontekst roli (z kim/o czym rozmawia po angielsku): ${participant.role_context || 'brak'}`,
  `Czestotliwosc uzywania angielskiego: ${participant.frequency || 'brak'}`,
  `Samoocena uczestnika: ${participant.self_assessment || 'brak'}`,
  `Potrzeby wg managera/HR: ${participant.manager_needs || 'brak'}`,
  '',
  '## Kontekst biznesowy',
  `Typ klienta: ${lead.lead_type || 'brak'}`,
  `Branza: ${lead.industry || 'brak'}`,
  company.name ? `Firma: ${company.name}` : null,
  company.communication_processes ? `Procesy komunikacyjne w firmie: ${company.communication_processes}` : null,
  company.business_impact ? `Wplyw jezyka na biznes: ${company.business_impact}` : null,
  '',
  '## Notatki Przemka z discovery call',
  latestDiscovery.notes || 'brak notatek z discovery call (lub brak spotkania typu discovery dla tego leada)',
];

return [{ json: {
  assessment_id: guard.assessment_id,
  participant_id: guard.participant_id,
  lead_id: leadId,
  methodologist,
  user: lines.filter(l => l !== null).join('\n'),
} }];

// Sukces AI Agenta -> draft needs_summary, task weryfikacji dla metodyka, activity.
const src = $('Assemble context').item.json;
const res = $input.first().json;
const content = (res.output || '').trim();
if (!content) throw new Error('Pusta odpowiedz LLM: ' + JSON.stringify(res).slice(0, 400));
return [{ json: { ...src,
  patch: { Id: src.assessment_id, needs_summary: content, ai_status: 'ai_draft_ready' },
  task: { title: `Zweryfikuj needs summary (assessment #${src.assessment_id})`,
          status: 'todo', priority: 'high', assignee: src.methodologist,
          created_by_flow: 'W11',
          description: `assessment:${src.assessment_id} participant:${src.participant_id} lead:${src.lead_id}` },
  activity: { summary: `AI needs summary draft gotowy (assessment #${src.assessment_id})`,
              type: 'ai_analysis_done', flow: 'W11', triggered_by: 'system',
              payload: JSON.stringify({ assessment_id: src.assessment_id, lead_id: src.lead_id,
                model: 'anthropic/claude-sonnet-4.5' }) }
} }];

// AI Agent zawiodl po probach retry - cofnij ai_status na 'none' (przycisk
// znow klikalny), task naprawczy, activity z bledem.
const src = $('Assemble context').item.json;
const err = $input.first().json;
return [{ json: { ...src,
  patch: { Id: src.assessment_id, ai_status: 'none' },
  task: { title: `BLAD generowania needs summary (assessment #${src.assessment_id})`,
          status: 'todo', priority: 'high', assignee: src.methodologist,
          created_by_flow: 'W11',
          description: `assessment:${src.assessment_id} participant:${src.participant_id} lead:${src.lead_id}\n`
            + JSON.stringify(err).slice(0, 500) },
  activity: { summary: `Generowanie needs summary NIEUDANE (assessment #${src.assessment_id})`,
              type: 'automation_error', flow: 'W11', triggered_by: 'system',
              payload: JSON.stringify({ assessment_id: src.assessment_id, error: err }).slice(0, 800) }
} }];

// Brak wypelnionych ocen CEFR - nie wolac LLM na pusto, tylko poprosic o
// uzupelnienie audytu przed ponownym kliknieciem przycisku.
const guard = $('Guard').item.json;
const lead = $('Get lead').item.json || {};
const methodologist = ''; // lead.lead_type === 'B2B' ? 'dorota@coaction.pl' : 'aleksandra@coaction.pl';
return [{ json: {
  task: { title: `Uzupelnij oceny CEFR przed generowaniem needs summary (assessment #${guard.assessment_id})`,
          status: 'todo', priority: 'normal', assignee: methodologist,
          created_by_flow: 'W11',
          description: `assessment:${guard.assessment_id} participant:${guard.participant_id}` },
  activity: { summary: `Needs summary: brak ocen CEFR (assessment #${guard.assessment_id})`,
              type: 'automation_error', flow: 'W11', triggered_by: 'user',
              payload: JSON.stringify({ assessment_id: guard.assessment_id }) }
} }];
